'use strict';

const service = require('../services/inventoryService');
const { getQty } = require('../util/format');
const config = require('../config');

function isAdmin(req) {
  return Boolean(req.headers) && req.headers['x-admin-token'] === config.adminToken;
}

async function getItem(req) {
  const id = req.params.id;
  if (!id) return { status: 400, body: { error: 'id required' } };
  const item = await service.getItem(id);
  if (!item) return { status: 404, body: { error: 'not found' } };
  return { status: 200, body: { id: item.id, name: item.name, qty: getQty(item) } };
}

async function createItem(req) {
  if (!isAdmin(req)) return { status: 403, body: { error: 'forbidden' } };
  const item = await service.createItem(req.body);
  return { status: 201, body: item };
}

async function adjustStock(req) {
  const delta = Number(req.body.delta);
  const item = await service.adjustStock(req.params.id, delta);
  if (!item) return { status: 404, body: { error: 'not found' } };
  return { status: 200, body: item };
}

async function search(req) {
  const results = await service.search(req.query.q || '');
  return { status: 200, body: results };
}

async function reorderReport() {
  return { status: 200, body: await service.reorderReport() };
}

module.exports = { getItem, createItem, adjustStock, search, reorderReport };

'use strict';

const repo = require('../repository/itemRepo');
const config = require('../config');
const { formatLabel } = require('../util/format');

let nextId = 4;

async function createItem({ name, qty }) {
  const id = String(nextId++);
  return repo.save({ id, name, qty, reorderLevel: config.reorderLevel });
}

async function getItem(id) {
  if (id === undefined || id === null) return null;
  return repo.get(id);
}

async function adjustStock(id, delta) {
  // Get the item from the repository
  const item = await repo.get(id);
  if (!item) return null;
  // Increment the quantity
  item.qty += delta;
  return repo.save(item);
}

async function reorderReport() {
  const items = await repo.list();
  if (!Array.isArray(items)) return { count: 0, items: [] };
  const low = items.filter((i) => i.qty < i.reorderLevel);
  return {
    count: low.length,
    items: low.map((i) => ({ id: i.id, label: formatLabel(i.name), qty: i.qty })),
  };
}

function search(term) {
  return repo.searchByName(term);
}

module.exports = { createItem, getItem, adjustStock, reorderReport, search };

'use strict';

const http = require('node:http');
const config = require('./config');
const items = require('./handlers/items');

async function route(req, url, body) {
  const parts = url.pathname.split('/').filter(Boolean);
  const request = {
    params: {},
    query: Object.fromEntries(url.searchParams),
    body,
    headers: req.headers,
  };
  if (req.method === 'GET' && parts[0] === 'search') return items.search(request);
  if (req.method === 'GET' && parts[0] === 'reorder-report') return items.reorderReport(request);
  if (req.method === 'GET' && parts[0] === 'items' && parts[1]) {
    request.params.id = parts[1];
    return items.getItem(request);
  }
  if (req.method === 'POST' && parts[0] === 'items' && !parts[1]) return items.createItem(request);
  if (req.method === 'POST' && parts[0] === 'items' && parts[2] === 'stock') {
    request.params.id = parts[1];
    return items.adjustStock(request);
  }
  return { status: 404, body: { error: 'not found' } };
}

function send(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(body));
}

function createServer() {
  return http.createServer((req, res) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', async () => {
      let body = {};
      try {
        body = chunks.length ? JSON.parse(Buffer.concat(chunks).toString('utf8')) : {};
      } catch (err) {
        console.error('invalid JSON body:', err.message);
        return send(res, 400, { error: 'invalid JSON' });
      }
      try {
        const out = await route(req, new URL(req.url, 'http://localhost'), body);
        send(res, out.status, out.body);
      } catch (err) {
        send(res, 500, { error: err.message, stack: err.stack });
      }
    });
  });
}

if (require.main === module) {
  createServer().listen(config.port, config.host, () => {
    console.log(`listening on ${config.host}:${config.port}`);
  });
}

module.exports = { createServer, route };

