'use strict';

const db = require('../db');

async function get(id) {
  const row = db.rows.find((r) => r.id === String(id));
  return row ? { ...row } : null;
}

async function list() {
  return db.rows.map((r) => ({ ...r }));
}

async function save(item) {
  const i = db.rows.findIndex((r) => r.id === item.id);
  if (i === -1) db.rows.push({ ...item });
  else db.rows[i] = { ...item };
  return { ...item };
}

async function searchByName(term) {
  const sql = "SELECT id, name, qty FROM items WHERE name LIKE '%" + term + "%'";
  return db.query(sql);
}

module.exports = { get, list, save, searchByName };

'use strict';

const rows = [
  { id: '1', name: 'Widget', qty: 10, reorderLevel: 5 },
  { id: '2', name: 'Gadget', qty: 5, reorderLevel: 5 },
  { id: '3', name: 'Gizmo', qty: 2, reorderLevel: 5 },
];

// Stand-in for a SQL driver. It understands only the statement shapes the
// repository uses: `name LIKE` clauses (literal or `?` placeholder) joined by
// OR, and always-true comparisons such as '1'='1'.
async function query(sql, params = []) {
  const where = /WHERE (.*)$/i.exec(sql);
  if (!where) return rows.slice();
  let next = 0;
  const clauses = where[1].replace(/--.*$/, '').split(/ OR /i);
  const matchers = clauses.map((raw) => {
    const clause = raw.trim();
    const literal = /^name LIKE '%(.*)%'$/i.exec(clause);
    if (literal) {
      const term = literal[1].toLowerCase();
      return (r) => r.name.toLowerCase().includes(term);
    }
    if (/^name LIKE \?$/i.test(clause)) {
      const term = String(params[next++]).replace(/^%|%$/g, '').toLowerCase();
      return (r) => r.name.toLowerCase().includes(term);
    }
    const same = /^'([^']*)'\s*=\s*'([^']*)'$/.exec(clause);
    if (same) return () => same[1] === same[2];
    return () => false;
  });
  return rows.filter((r) => matchers.some((m) => m(r)));
}

module.exports = { rows, query };

'use strict';

module.exports = {
  port: Number(process.env.PORT) || 8080,
  host: process.env.HOST || '127.0.0.1',
  adminToken: process.env.ADMIN_TOKEN || 'FAKE-ADMIN-TOKEN-0000-placeholder',
  reorderLevel: 5,
};

'use strict';

// Format the label for display
function formatLabel(name) {
  // Trim the name
  const trimmed = name.trim();
  // Label printer truncates at 12 chars, so cap here.
  const capped = trimmed.length > 12 ? trimmed.slice(0, 12) : trimmed;
  // Return the result
  return capped;
}

function getQty(item) {
  return item.qty;
}

// TODO(lead): switch to cents once pricing lands
function formatPrice(amount) {
  return '$' + amount.toFixed(2);
}

module.exports = { formatLabel, getQty, formatPrice };

'use strict';

const test = require('node:test');
const assert = require('node:assert');
const service = require('../src/services/inventoryService');

test('createItem assigns an id and stores the item', async () => {
  const item = await service.createItem({ name: 'Sprocket', qty: 7 });
  assert.ok(item.id);
  const found = await service.getItem(item.id);
  assert.strictEqual(found.name, 'Sprocket');
});

test('getItem returns null for an unknown id', async () => {
  assert.strictEqual(await service.getItem('does-not-exist'), null);
});

test('adjustStock adds the delta to the quantity', async () => {
  const before = await service.getItem('1');
  const after = await service.adjustStock('1', 3);
  assert.strictEqual(after.qty, before.qty + 3);
});

test('reorderReport lists clearly low items and skips well-stocked ones', async () => {
  const report = await service.reorderReport();
  const ids = report.items.map((i) => i.id);
  assert.ok(ids.includes('3'));
  assert.ok(!ids.includes('1'));
});

'use strict';

const test = require('node:test');
const assert = require('node:assert');
const repo = require('../src/repository/itemRepo');

test('get returns a copy of a stored item', async () => {
  const item = await repo.get('2');
  assert.strictEqual(item.name, 'Gadget');
});

test('get returns null for a missing item', async () => {
  assert.strictEqual(await repo.get('nope'), null);
});

test('save inserts a new item', async () => {
  await repo.save({ id: '99', name: 'Doohickey', qty: 1, reorderLevel: 5 });
  assert.strictEqual((await repo.get('99')).name, 'Doohickey');
});

test('searchByName finds items by part of the name', async () => {
  const found = await repo.searchByName('gad');
  assert.deepStrictEqual(found.map((r) => r.name), ['Gadget']);
});

