'use strict';

const NAME_MAX_LENGTH = 100;

// Thrown for any input the caller can fix. Handlers map it to a 400 response;
// anything else is an unexpected failure and keeps propagating (500).
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// Number.isSafeInteger rejects NaN, Infinity, floats and strings without
// coercion. It also rejects integers beyond 2^53, where arithmetic would
// silently lose precision.
function isIntegerNumber(value) {
  return Number.isSafeInteger(value);
}

function assertBodyObject(body) {
  if (!isPlainObject(body)) {
    throw new ValidationError('request body must be a JSON object');
  }
}

// Length is measured in JavaScript string units (UTF-16 code units).
// Whitespace-only names count as empty, but the name is stored as given.
function assertName(name) {
  if (typeof name !== 'string' || name.trim().length === 0 || name.length > NAME_MAX_LENGTH) {
    throw new ValidationError(
      `name must be a non-empty string of at most ${NAME_MAX_LENGTH} characters`
    );
  }
}

function assertQty(qty) {
  if (!isIntegerNumber(qty) || qty < 0) {
    throw new ValidationError('qty must be a non-negative integer');
  }
}

function assertDelta(delta) {
  if (!isIntegerNumber(delta)) {
    throw new ValidationError('delta must be a finite integer');
  }
}

// Validates the POST /items body. Returns only the fields the service uses.
function validateNewItem(body) {
  assertBodyObject(body);
  assertName(body.name);
  assertQty(body.qty);
  return { name: body.name, qty: body.qty };
}

// Validates the POST /items/:id/stock body and returns the delta.
function validateStockAdjustment(body) {
  assertBodyObject(body);
  assertDelta(body.delta);
  return body.delta;
}

// The stock floor needs the current quantity, so the service calls this after
// it has read the item.
function assertResultingQty(currentQty, delta) {
  const next = currentQty + delta;
  if (next < 0) {
    throw new ValidationError(
      `stock cannot go below zero: delta ${delta} exceeds available qty ${currentQty}`
    );
  }
  if (!isIntegerNumber(next)) {
    throw new ValidationError('resulting qty is too large');
  }
  return next;
}

module.exports = {
  NAME_MAX_LENGTH,
  ValidationError,
  assertDelta,
  assertResultingQty,
  validateNewItem,
  validateStockAdjustment,
};

