'use strict';

const test = require('node:test');
const assert = require('node:assert');
const {
  ValidationError,
  assertResultingQty,
  validateNewItem,
  validateStockAdjustment,
} = require('../src/validation');

const NAME_MSG = 'name must be a non-empty string of at most 100 characters';
const QTY_MSG = 'qty must be a non-negative integer';
const DELTA_MSG = 'delta must be a finite integer';
const BODY_MSG = 'request body must be a JSON object';

function rejects(fn, message) {
  assert.throws(fn, (err) => err instanceof ValidationError && err.message === message);
}

test('validateNewItem accepts a valid body and returns only name and qty', () => {
  assert.deepStrictEqual(validateNewItem({ name: 'Bolt', qty: 3, extra: 'x' }), {
    name: 'Bolt',
    qty: 3,
  });
});

test('validateNewItem name: length 1 and 100 pass, 101 fails', () => {
  assert.strictEqual(validateNewItem({ name: 'a', qty: 0 }).name, 'a');
  assert.strictEqual(validateNewItem({ name: 'a'.repeat(100), qty: 0 }).name.length, 100);
  rejects(() => validateNewItem({ name: 'a'.repeat(101), qty: 0 }), NAME_MSG);
});

test('validateNewItem name: empty, whitespace-only, missing and non-strings fail', () => {
  for (const name of ['', '   ', '\t\n', undefined, null, 5, true, [], ['a'], {}]) {
    rejects(() => validateNewItem({ name, qty: 1 }), NAME_MSG);
  }
  rejects(() => validateNewItem({ qty: 1 }), NAME_MSG);
});

test('validateNewItem keeps the name as given (no trimming)', () => {
  assert.strictEqual(validateNewItem({ name: '  Bolt  ', qty: 1 }).name, '  Bolt  ');
});

test('validateNewItem qty: 0 and positive integers pass', () => {
  assert.strictEqual(validateNewItem({ name: 'a', qty: 0 }).qty, 0);
  assert.strictEqual(validateNewItem({ name: 'a', qty: 42 }).qty, 42);
});

test('validateNewItem qty: negative, float, string and other types fail', () => {
  for (const qty of [-1, 1.5, '3', '', null, undefined, true, [], [1], {}, NaN, Infinity, -Infinity]) {
    rejects(() => validateNewItem({ name: 'a', qty }), QTY_MSG);
  }
  rejects(() => validateNewItem({ name: 'a' }), QTY_MSG);
});

test('validateNewItem reports the name problem before the qty problem', () => {
  rejects(() => validateNewItem({ name: '', qty: -1 }), NAME_MSG);
});

test('body must be a JSON object', () => {
  for (const body of [null, undefined, [], [{ name: 'a', qty: 1 }], 'text', 5, true]) {
    rejects(() => validateNewItem(body), BODY_MSG);
    rejects(() => validateStockAdjustment(body), BODY_MSG);
  }
});

test('validateStockAdjustment accepts zero, negative and positive integers', () => {
  assert.strictEqual(validateStockAdjustment({ delta: 0 }), 0);
  assert.strictEqual(validateStockAdjustment({ delta: -4 }), -4);
  assert.strictEqual(validateStockAdjustment({ delta: 7 }), 7);
});

test('validateStockAdjustment rejects floats, NaN, Infinity, strings and other types', () => {
  const bad = [1.5, -0.5, NaN, Infinity, -Infinity, '5', '', ' 5 ', null, undefined, true, false, [], [5], {}, 1e300];
  for (const delta of bad) {
    rejects(() => validateStockAdjustment({ delta }), DELTA_MSG);
  }
  rejects(() => validateStockAdjustment({}), DELTA_MSG);
});

test('assertResultingQty returns the new quantity', () => {
  assert.strictEqual(assertResultingQty(5, 3), 8);
  assert.strictEqual(assertResultingQty(5, -5), 0);
  assert.strictEqual(assertResultingQty(5, 0), 5);
});

test('assertResultingQty rejects a result below zero with a clear message', () => {
  rejects(
    () => assertResultingQty(3, -4),
    'stock cannot go below zero: delta -4 exceeds available qty 3'
  );
});

test('assertResultingQty rejects a result beyond the safe integer range', () => {
  rejects(() => assertResultingQty(Number.MAX_SAFE_INTEGER, 1), 'resulting qty is too large');
});

