const test = require('node:test');
const assert = require('node:assert');
const items = require('../src/handlers/items');
const service = require('../src/services/inventoryService');
const config = require('../src/config');
const { createServer } = require('../src/server');

const admin = { 'x-admin-token': config.adminToken };

function create(body, headers = admin) {
  return items.createItem({ params: {}, query: {}, headers, body });
}

function adjust(id, body) {
  return items.adjustStock({ params: { id }, query: {}, headers: {}, body });
}

async function newItem(qty) {
  const res = await create({ name: 'Fixture', qty });
  assert.strictEqual(res.status, 201);
  return res.body;
}

// ---- POST /items (handler) ----

test('createItem returns 201 for a valid body, including boundary values', async () => {
  const longest = await create({ name: 'a'.repeat(100), qty: 0 });
  assert.strictEqual(longest.status, 201);
  assert.strictEqual(longest.body.name.length, 100);
  assert.strictEqual(longest.body.qty, 0);
});

test('createItem returns 400 with the name message for bad names', async () => {
  const msg = 'name must be a non-empty string of at most 100 characters';
  for (const name of ['', '   ', 'a'.repeat(101), undefined, null, 7]) {
    const res = await create({ name, qty: 1 });
    assert.deepStrictEqual(res, { status: 400, body: { error: msg } });
  }
});

test('createItem returns 400 with the qty message for bad quantities', async () => {
  const msg = 'qty must be a non-negative integer';
  for (const qty of [-1, 1.5, '3', null, undefined, NaN, Infinity]) {
    const res = await create({ name: 'Ok', qty });
    assert.deepStrictEqual(res, { status: 400, body: { error: msg } });
  }
});

test('createItem returns 400 for a missing or non-object body', async () => {
  for (const body of [undefined, null, [], 'text', 5]) {
    const res = await create(body);
    assert.deepStrictEqual(res, { status: 400, body: { error: 'request body must be a JSON object' } });
