const service = require('../src/services/inventoryService');
const config = require('../src/config');
const { createServer } = require('../src/server');

const admin = { 'x-admin-token': config.adminToken };

function create(body, headers = admin) {
  return items.createItem({ params: {}, query: {}, headers, body });
}

function adjust(id, body) {
  return items.adjustStock({ params: { id }, query: {}, headers: {}, body });
}

async function newItem(qty) {
  const res = await create({ name: 'Fixture', qty });
  assert.strictEqual(res.status, 201);
  return res.body;
}

// ---- POST /items (handler) ----

test('createItem returns 201 for a valid body, including boundary values', async () => {
  const longest = await create({ name: 'a'.repeat(100), qty: 0 });
  assert.strictEqual(longest.status, 201);
  assert.strictEqual(longest.body.name.length, 100);
  assert.strictEqual(longest.body.qty, 0);
});

test('createItem returns 400 with the name message for bad names', async () => {
  const msg = 'name must be a non-empty string of at most 100 characters';
  for (const name of ['', '   ', 'a'.repeat(101), undefined, null, 7]) {
    const res = await create({ name, qty: 1 });
    assert.deepStrictEqual(res, { status: 400, body: { error: msg } });
  }
});

test('createItem returns 400 with the qty message for bad quantities', async () => {
  const msg = 'qty must be a non-negative integer';
  for (const qty of [-1, 1.5, '3', null, undefined, NaN, Infinity]) {
    const res = await create({ name: 'Ok', qty });
    assert.deepStrictEqual(res, { status: 400, body: { error: msg } });
  }
});

test('createItem returns 400 for a missing or non-object body', async () => {
  for (const body of [undefined, null, [], 'text', 5]) {
    const res = await create(body);
    assert.deepStrictEqual(res, { status: 400, body: { error: 'request body must be a JSON object' } });
  }
});

test('createItem does not store anything when validation fails', async () => {
  const before = await service.search('NoSuchItemMarker');
  await create({ name: 'NoSuchItemMarker', qty: -1 });
  assert.deepStrictEqual(await service.search('NoSuchItemMarker'), before);
});

test('createItem still returns 403 before validating when the admin token is wrong', async () => {
  const res = await create({ name: '', qty: -1 }, { 'x-admin-token': 'wrong' });
  assert.deepStrictEqual(res, { status: 403, body: { error: 'forbidden' } });
  assert.strictEqual((await create({ name: '', qty: -1 }, undefined)).status, 403);
});

// ---- POST /items/:id/stock (handler) ----

test('adjustStock accepts zero, positive and negative integer deltas', async () => {
  const { id } = await newItem(10);
  assert.strictEqual((await adjust(id, { delta: 0 })).body.qty, 10);
  assert.strictEqual((await adjust(id, { delta: 5 })).body.qty, 15);
  assert.strictEqual((await adjust(id, { delta: -3 })).body.qty, 12);
});

test('adjustStock returns 400 for floats, NaN, Infinity, strings and other types', async () => {
  const { id } = await newItem(10);
  for (const delta of [1.5, NaN, Infinity, -Infinity, '5', null, true, [], [5], {}, undefined]) {
    const res = await adjust(id, { delta });
    assert.deepStrictEqual(res, { status: 400, body: { error: 'delta must be a finite integer' } });
  }
  assert.strictEqual((await service.getItem(id)).qty, 10);
});

test('adjustStock returns 400 for a missing or non-object body', async () => {
  const { id } = await newItem(10);
  for (const body of [undefined, null, [], 'text', 5]) {
    const res = await adjust(id, body);
    assert.deepStrictEqual(res, { status: 400, body: { error: 'request body must be a JSON object' } });
  }
});

test('adjustStock rejects removing more than available and leaves qty unchanged', async () => {
  const { id } = await newItem(3);
  const res = await adjust(id, { delta: -4 });
  assert.strictEqual(res.status, 400);
  assert.strictEqual(res.body.error, 'stock cannot go below zero: delta -4 exceeds available qty 3');
  assert.strictEqual((await service.getItem(id)).qty, 3);
});

test('adjustStock allows removing exactly all stock', async () => {
  const { id } = await newItem(3);
  const res = await adjust(id, { delta: -3 });
  assert.strictEqual(res.status, 200);
  assert.strictEqual(res.body.qty, 0);
  assert.strictEqual((await adjust(id, { delta: -1 })).status, 400);
  assert.strictEqual((await service.getItem(id)).qty, 0);
});

test('adjustStock returns 404 for an unknown id with a valid delta', async () => {
  const res = await adjust('does-not-exist', { delta: 1 });
  assert.deepStrictEqual(res, { status: 404, body: { error: 'not found' } });
});

test('adjustStock checks delta shape before the id lookup', async () => {
  const res = await adjust('does-not-exist', { delta: 'x' });
  assert.strictEqual(res.status, 400);
});

test('adjustStock checks the id before the below-zero rule', async () => {
  const res = await adjust('does-not-exist', { delta: -1000 });
  assert.strictEqual(res.status, 404);
});

test('concurrent removals cannot take stock below zero', async () => {
  const { id } = await newItem(5);
  const results = await Promise.all([adjust(id, { delta: -3 }), adjust(id, { delta: -3 })]);
  assert.deepStrictEqual(results.map((r) => r.status).sort(), [200, 400]);
  assert.strictEqual((await service.getItem(id)).qty, 2);
});

test('service.adjustStock rejects a non-integer delta even when called directly', async () => {
  const { id } = await newItem(5);
  await assert.rejects(() => service.adjustStock(id, NaN), /delta must be a finite integer/);
  assert.strictEqual((await service.getItem(id)).qty, 5);
});

// ---- HTTP, end to end ----

async function withServer(fn) {
  const server = createServer();
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  try {
    await fn(base);
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
}

async function post(base, path, rawBody, headers = admin) {
  const res = await fetch(base + path, {
    method: 'POST',
    headers: { 'content-type': 'application/json', ...headers },
    body: rawBody,
  });
  return { status: res.status, body: await res.json() };
}

test('HTTP POST /items returns 400 with the message for invalid input', async () => {
  await withServer(async (base) => {
    assert.deepStrictEqual(await post(base, '/items', JSON.stringify({ name: 'a'.repeat(101), qty: 1 })), {
      status: 400,
      body: { error: 'name must be a non-empty string of at most 100 characters' },
    });
    assert.deepStrictEqual(await post(base, '/items', JSON.stringify({ name: 'Ok', qty: '3' })), {
      status: 400,
      body: { error: 'qty must be a non-negative integer' },
    });
    for (const raw of ['null', '[]', '"text"', '5']) {
      assert.deepStrictEqual(await post(base, '/items', raw), {
        status: 400,
        body: { error: 'request body must be a JSON object' },
      });
    }
  });
});

test('HTTP POST /items returns 201 for valid input and 403 without the token', async () => {
  await withServer(async (base) => {
    const ok = await post(base, '/items', JSON.stringify({ name: 'Over HTTP', qty: 0 }));
    assert.strictEqual(ok.status, 201);
    assert.strictEqual(ok.body.name, 'Over HTTP');
    const denied = await post(base, '/items', JSON.stringify({ name: '', qty: -1 }), {});
    assert.strictEqual(denied.status, 403);
  });
});

test('HTTP POST /items/:id/stock returns 400 with the message for invalid input', async () => {
  await withServer(async (base) => {
    const { id } = await newItem(3);
    const path = `/items/${id}/stock`;
    assert.deepStrictEqual(await post(base, path, JSON.stringify({ delta: '5' })), {
      status: 400,
      body: { error: 'delta must be a finite integer' },
    });
    assert.deepStrictEqual(await post(base, path, JSON.stringify({ delta: 1.5 })), {
      status: 400,
      body: { error: 'delta must be a finite integer' },
    });
    assert.deepStrictEqual(await post(base, path, 'null'), {
      status: 400,
      body: { error: 'request body must be a JSON object' },
    });
    assert.deepStrictEqual(await post(base, path, JSON.stringify({ delta: -4 })), {
      status: 400,
      body: { error: 'stock cannot go below zero: delta -4 exceeds available qty 3' },
    });
    assert.strictEqual((await service.getItem(id)).qty, 3);
    assert.strictEqual((await post(base, path, JSON.stringify({ delta: -3 }))).body.qty, 0);
    assert.strictEqual((await post(base, '/items/nope/stock', JSON.stringify({ delta: 1 }))).status, 404);
  });
});

'use strict';

const test = require('node:test');
const assert = require('node:assert');
const {
  ValidationError,
  assertResultingQty,
  validateNewItem,
  validateStockAdjustment,
} = require('../src/validation');

const NAME_MSG = 'name must be a non-empty string of at most 100 characters';
const QTY_MSG = 'qty must be a non-negative integer';
const DELTA_MSG = 'delta must be a finite integer';
const BODY_MSG = 'request body must be a JSON object';

function rejects(fn, message) {
  assert.throws(fn, (err) => err instanceof ValidationError && err.message === message);
}

test('validateNewItem accepts a valid body and returns only name and qty', () => {
  assert.deepStrictEqual(validateNewItem({ name: 'Bolt', qty: 3, extra: 'x' }), {
    name: 'Bolt',
    qty: 3,
  });
});

test('validateNewItem name: length 1 and 100 pass, 101 fails', () => {
  assert.strictEqual(validateNewItem({ name: 'a', qty: 0 }).name, 'a');
  assert.strictEqual(validateNewItem({ name: 'a'.repeat(100), qty: 0 }).name.length, 100);
  rejects(() => validateNewItem({ name: 'a'.repeat(101), qty: 0 }), NAME_MSG);
});

test('validateNewItem name: empty, whitespace-only, missing and non-strings fail', () => {
  for (const name of ['', '   ', '\t\n', undefined, null, 5, true, [], ['a'], {}]) {
    rejects(() => validateNewItem({ name, qty: 1 }), NAME_MSG);
  }
  rejects(() => validateNewItem({ qty: 1 }), NAME_MSG);
});

test('validateNewItem keeps the name as given (no trimming)', () => {
  assert.strictEqual(validateNewItem({ name: '  Bolt  ', qty: 1 }).name, '  Bolt  ');
});

test('validateNewItem qty: 0 and positive integers pass', () => {
  assert.strictEqual(validateNewItem({ name: 'a', qty: 0 }).qty, 0);
  assert.strictEqual(validateNewItem({ name: 'a', qty: 42 }).qty, 42);
});

test('validateNewItem qty: negative, float, string and other types fail', () => {
  for (const qty of [-1, 1.5, '3', '', null, undefined, true, [], [1], {}, NaN, Infinity, -Infinity]) {
    rejects(() => validateNewItem({ name: 'a', qty }), QTY_MSG);
  }
  rejects(() => validateNewItem({ name: 'a' }), QTY_MSG);
});

test('validateNewItem reports the name problem before the qty problem', () => {
  rejects(() => validateNewItem({ name: '', qty: -1 }), NAME_MSG);
});

test('body must be a JSON object', () => {
  for (const body of [null, undefined, [], [{ name: 'a', qty: 1 }], 'text', 5, true]) {
    rejects(() => validateNewItem(body), BODY_MSG);
    rejects(() => validateStockAdjustment(body), BODY_MSG);
  }
});

test('validateStockAdjustment accepts zero, negative and positive integers', () => {
  assert.strictEqual(validateStockAdjustment({ delta: 0 }), 0);
  assert.strictEqual(validateStockAdjustment({ delta: -4 }), -4);
  assert.strictEqual(validateStockAdjustment({ delta: 7 }), 7);
});

test('validateStockAdjustment rejects floats, NaN, Infinity, strings and other types', () => {
  const bad = [1.5, -0.5, NaN, Infinity, -Infinity, '5', '', ' 5 ', null, undefined, true, false, [], [5], {}, 1e300];
  for (const delta of bad) {
    rejects(() => validateStockAdjustment({ delta }), DELTA_MSG);
  }
  rejects(() => validateStockAdjustment({}), DELTA_MSG);
});

test('assertResultingQty returns the new quantity', () => {
  assert.strictEqual(assertResultingQty(5, 3), 8);
  assert.strictEqual(assertResultingQty(5, -5), 0);
  assert.strictEqual(assertResultingQty(5, 0), 5);
});

test('assertResultingQty rejects a result below zero with a clear message', () => {
  rejects(
    () => assertResultingQty(3, -4),
    'stock cannot go below zero: delta -4 exceeds available qty 3'
  );
});

test('assertResultingQty rejects a result beyond the safe integer range', () => {
  rejects(() => assertResultingQty(Number.MAX_SAFE_INTEGER, 1), 'resulting qty is too large');
});

