  console.log('stock unknown id bad delta =>',await call('POST','/items/zzz/stock','{"delta":"1"}'));
  console.log('stock unknown id neg =>',await call('POST','/items/zzz/stock','{"delta":-1}'));
  console.log('stock id1 -50 =>',await call('POST','/items/1/stock','{"delta":-50}'));
  console.log('GET /items/1 =>',await call('GET','/items/1'));
  console.log('reorder =>',await call('GET','/reorder-report'));
  s.close();
});
EOF
